(* [comment removed for export] *)
Ltac prove_inside_insW :=
  first [ apply inside_insW_frame; lia
        | apply inside_insW_hdr; lia
        | match goal with
          | H : ?a ∈ ?E |- inside (insW _ _ _ ?E) _ _ => apply (inside_insW_elem _ _ _ _ a _ _ H); lia
          end
        | match goal with
          | H : ?a ∈ ?L0 |- inside (insW _ _ _ (_ :: ?L0)) _ _ => apply (inside_insW_elem _ _ _ _ a); [rewrite elem_of_cons; right; exact H| lia| lia]
          end
        | match goal with
          | |- inside (insW _ _ _ (?a :: _)) _ _ => apply (inside_insW_elem _ _ _ _ a); [rewrite elem_of_cons; left; reflexivity| lia| lia]
          end ].

Ltac footprint_after_store segs m a bs ::=
  repeat match goal with
  | MU : munch ?Wq ?mq m |- _ =>
      first [ apply (munch_write Wq mq m a bs) in MU; [ | lia | simpl_sizes; slia | first [prove_inside_ibW | simpl_sizes; prove_inside_insW] ]
            | fail 100 "store outside the declared footprint:" a ]
  | WMo : wmono segs ?mq m |- _ => apply (wmono_write segs mq m (wa a) bs) in WMo
  | STq : stk segs m ?loq ?hiq |- _ =>
      first [ apply (stk_write segs m loq hiq a bs) in STq; [ | lia | simpl_sizes; slia ]
            | fail 100 "cannot transport stk hypothesis" STq ]
  end.

(* [comment removed for export] *)
Ltac transport_after_call_ins segs m m' MU WM :=
  let W := lazymatch type of MU with munch ?W _ _ => W end in
  repeat match goal with
  | H : bytes_at segs m ?A2 ?bs2 |- _ =>
      first [ apply (bytes_at_transport segs W m m' A2 bs2) in H; [ | exact MU | cbn [disjoint_from]; simpl_sizes; slia ]
            | lazymatch W with ibW ?lo ?hi ?X =>
                apply (bytes_at_ibW lo hi X m m' A2 bs2) in H; [ | exact MU | simpl_sizes; lia | ibW_disj_nodes ] end
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : wr_at segs m ?A2 ?n2 |- _ => apply (wr_at_transport segs m m' A2 n2) in H; [ | exact WM ]
  | H : rw_cells segs m ?A2 ?cs2 |- _ =>
      first [ apply (rw_cells_transport segs W m m' A2 cs2) in H; [ | exact MU | exact WM | cbn [disjoint_from]; simpl_sizes; slia ]
            | lazymatch W with ibW ?lo ?hi ?X =>
                apply (rw_cells_ibW lo hi X m m' A2 cs2) in H; [ | exact MU | exact WM | simpl_sizes; lia | ibW_disj_nodes ] end
            | idtac "note: dropping hypothesis (not provably disjoint from callee footprint):" H; clear H ]
  | H : stk segs m ?loq ?hiq |- _ =>
