Definition insel_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (Fa e : Z) (d : elt) (L : list Z) (em : gmap Z elt) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' S' L' ns' ls',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (insW lo (bv_unsigned sp) Fa (e :: L)) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ FieldsC m' Fa S' L' ns' ls' (<[e := d]> em)
    /\ (e + 16) ∈ S' /\ e ∈ L'.

Definition insel_stmt : Prop := forall (Fa e : Z) (d : elt) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt)
    (lo : Z) (junk : list byte)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FieldsC m Fa S L ns ls em ->
  rw_cells usegs m e [CB 48 junk] -> rw_cells usegs m (e + 48) (ValCells d) -> new_elt_ok em e d ->
  stk usegs m lo (bv_unsigned sp) -> lo + INSEL_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= Fa ->
  bv_unsigned sp mod 16 = 0 ->                                                  (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (insel_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc Fa e d L em lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz Fa) (wz e) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FIELDS_INSERT_ELEMENT) fc None m (seg_rom usegs)).


(* [comment removed for export] *)
Lemma FieldsC_LSR_new : forall m Fa S L ns ls em e d j16 lo (sp : word),
  FieldsC m Fa S L ns ls em -> new_elt_ok em e d ->
