Section IE.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (Fa e f : Z) (name value pad tail : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt).
  Variables (lo : Z) (junk : list byte).
  Let d := mkElt f name value pad tail.
  Hypothesis FC : FieldsC m Fa S L ns ls em.
  Hypothesis NEW : new_elt_ok em e d.
  Hypothesis LO : lo + 240 <= bv_unsigned sp.
  Hypothesis HC : hceil <= lo.
  Hypothesis SPF : bv_unsigned sp <= Fa.
  Hypothesis SPAL : bv_unsigned sp mod 16 = 0.                     (* [comment removed for export] *)

  Let kb := zbytes name.
  Let key := key_of em.
  Let ubA := ub_prefix key_lt key kb S.
  Let ubB := ub_suffix key_lt key kb S.
  Let before := lhead Fa ubB.
  Let fuel := Datatypes.S (length S).
  Let X := Fa :: (e + 16) :: S.

  (* [comment removed for export] *)
  Definition ie_mem (m1 : mem) (w0 w8 : word) : Prop :=
    rw_cells usegs m1 (bv_unsigned sp + -80) [C8 w0; C8 w8]
    /\ rw_cells usegs m1 (bv_unsigned sp + -64) [C8 (Z_to_bv 64 Fa); C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells usegs m1 e [CB 48 junk] /\ rw_cells usegs m1 (e + 48) (ValCells d) /\ bytes_at usegs m1 (e + 56) name
    /\ munch (insW lo (bv_unsigned sp) Fa (e :: L)) m m1 /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono usegs m m1
    /\ mem_inv usegs m1 /\ stk usegs m1 lo (bv_unsigned sp + -80).

  (* [comment removed for export] *)
  Local Ltac ie_pure :=
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR; hcb;
    pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & HHF & HB & ALF);
    pose proof NEW as (EP & EAL & EHI & WFd & DJ);
    destruct (new_elt_fresh _ _ _ _ _ _ _ _ _ FC NEW) as (NONE & NL & NS & NEF & NE0 & E0 & KAG & KNEW & EOK');
    pose proof (rb_ok_rep _ _ _ OK) as RR; pose proof (rb_rep_nodup _ _ _ RR) as ND;
    pose proof (ub_split key_lt key kb S : S = ubA ++ ubB) as ES;
    unfold elt_wf, esize in EHI, WFd; cbn [d el_f el_name el_value el_pad el_tail] in EHI, WFd;
    unfold zlength in WFd, EHI;
    assert (EG : esize d = 60 + Z.of_nat (length name) + Z.of_nat (length value) + Z.of_nat (length tail)) by reflexivity.

  Local Ltac ie_open M :=
    destruct M as (KV & FRH & HK & PL & NB & MU & MUf & WM & MI & ST);
